/* eslint-disable */
/**
 * The landing page's own behaviour: the noise words, the feed you can put down,
 * the entry you can write, the chart and the memory rows.
 *
 * Imperative on purpose. The page was carried across whole rather than
 * decomposed, the same way the journal app was, so that changes on either side
 * can still be read against each other. Everything it borrows from the journal
 * comes through APP, which is generated by scripts/lift-journal.mjs.
 */
import { APP } from './lifted.js';
import KIT from '../../journal/sample.json';

/** Wire up a landing page that is already in the document. Returns a cleanup. */
export function runLanding() {
  const cleanups = [];
  const on = (target, type, fn, opts) => {
    target.addEventListener(type, fn, opts);
    cleanups.push(() => target.removeEventListener(type, fn, opts));
  };

  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const esc=s=>s.replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  /* The app's own star field, behind the page. Four magnitudes from a fixed
     seed, so the sky is the same sky on every visit and the same sky as the
     app's: the plotting below is the app's, through APP.seeded. */
  (function(){
    const a=$('#ambient');if(!a)return;
    const r=APP.seeded('sky');
    /* The app plots these magnitudes against near-black. Candle's ground is
       warmer and a stop lighter, so the same values sink into it: the faint
       end is lifted and there are more of them, to carry a page this long. */
    const stars=Array.from({length:260},()=>{
      const m=r()<.06?1:r()<.22?2:r()<.54?3:4;
      const z=[0,3,2.3,1.7,1.25][m], o=[0,1,.88,.7,.52][m];
      /* the draw happens either way, so reduced motion gets the same sky,
         just without the twinkle on it */
      const tw=m<=2&&r()<.55&&!reduce;
      return '<i class="st'+(tw?' tw':'')+'" style="left:'+(r()*100).toFixed(2)+'%;top:'+(r()*100).toFixed(2)+'%;--z:'+z+'px;--o:'+o
        +(tw?';--t:'+(4+r()*5).toFixed(1)+'s;--dl:'+(-r()*9).toFixed(1)+'s':'')+'"></i>';
    });
    a.innerHTML='<i class="band"></i>'+stars.join('');
  })();

  /* Putting the feed down is the argument: the motion stops and the colour
     drains out of it. */
  (function(){
    const wall=$('#feedWall'), loud=$('#feedLoud'), quiet=$('#feedQuiet');
    if(!wall)return;
    const set=(down)=>{wall.classList.toggle('quiet',down);loud.hidden=down;quiet.hidden=!down};
    $('#putDown')?.addEventListener('click',()=>set(true));
    $('#letBack')?.addEventListener('click',()=>set(false));
  })();

  /* Nav border */
  const nav=$('.nav');
  on(window,'scroll',()=>nav.classList.toggle('scrolled',scrollY>8),{passive:true});

  /* Scroll clock: night to morning and back */
  const clock=$('#clock'), clockT=$('#clockT');
  const toMin=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};
  const fmt=m=>{m=((Math.round(m)%1440)+1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')};
  let cur=toMin('23:41'), tween=0;
  function setTime(t){
    const target=toMin(t);let diff=((target-cur)%1440+1440)%1440;if(diff>720)diff-=1440;
    const from=cur, start=performance.now(), dur=reduce?0:700;cancelAnimationFrame(tween);
    const step=now=>{const k=dur?Math.min(1,(now-start)/dur):1, e=1-Math.pow(1-k,3);cur=from+diff*e;
      clockT.textContent=fmt(cur);const h=Math.floor((((Math.round(cur)%1440)+1440)%1440)/60);clock.classList.toggle('sun',h>=6&&h<19);
      if(k<1)tween=requestAnimationFrame(step);else cur=target};
    tween=requestAnimationFrame(step);
  }
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)setTime(e.target.dataset.time)}),{rootMargin:'-50% 0px -50% 0px'});
  $$('[data-time]').forEach(s=>io.observe(s));

  /* Hero noise */
  const hero=$('.hero'), words=$$('.word'), hint=$('#hint'), noise=$('#noise');
  let quieted=0;
  hero.addEventListener('pointermove',e=>{
    if(reduce||e.pointerType==='touch')return;
    const r=hero.getBoundingClientRect(), x=(e.clientX-r.left)/r.width-.5, y=(e.clientY-r.top)/r.height-.5;
    words.forEach(w=>{const d=+w.dataset.d||1;w.style.setProperty('--dx',(x*d*-28).toFixed(1)+'px');w.style.setProperty('--dy',(y*d*-20).toFixed(1)+'px')});
  });
  words.forEach(w=>{w.setAttribute('aria-label','Quiet "'+w.textContent+'"');w.addEventListener('click',()=>{
    if(w.classList.contains('gone'))return;w.classList.add('gone');quieted++;
    hint.textContent=quieted===words.length?'Quiet. Now, what’s actually on your mind?':quieted+' of '+words.length+' quieted';
    if(quieted===words.length)document.body.classList.add('quiet-sky');
  })});
  $('#quietBtn').addEventListener('click',()=>{
    hero.classList.add('quiet');document.body.classList.add('quiet-sky');hint.textContent='Quiet. Now, what’s actually on your mind?';
    setTimeout(()=>$('#how').scrollIntoView({behavior:reduce?'auto':'smooth'}),reduce?0:550);
  });
  on(window,'scroll',()=>{const h=hero.offsetHeight;noise.style.setProperty('--fade',Math.max(0,1-scrollY/(h*.75)).toFixed(3))},{passive:true});


  /* Survey dots: 42 students each */
  $$('.stat').forEach(s=>{const n=+s.dataset.n, d=$('.dots',s);d.innerHTML=Array.from({length:42},(_,i)=>'<span'+(i<n?' class="on"':'')+'></span>').join('')});

  /* Try one night */
  const SAMPLE="Three people from my year posted internship offers today. I closed Instagram, opened it again ten minutes later, and saved another “how I landed Goldman at 19” video. I don't even know if I want finance. The only part of this week that felt like mine was the photo walk on Sunday. I'm tired of feeling behind in a race I never signed up for.";
  const LETTERS={
    friend:{from:'From your Friend',greet:'Hey,',head:'The third night you wrote “behind”.',
      said:'Last night was a lot. Three people posted offers, you went back to Instagram twice, and you saved another video about landing finance at 19. Then you said it yourself: you’re not even sure you want finance.',
      rec:'This is the third night this week you wrote the word “behind.” And for the second time, the photo walk was the part of your week that felt like yours.',
      step:'Take your camera out for 20 minutes today, before you open Instagram.',sign:'Talk tonight,\nB.'},
    mentor:{from:'From your Mentor',greet:'Good morning.',head:'Two signals, both repeating.',
      said:'Here is what I heard. You measured yourself against three internship offers, spent the evening collecting advice for a path you’re unsure of, and ended the night tired.',
      rec:'Two signals repeat across your recent entries. Feeling behind tends to follow time on social apps (3 of 4 entries this week). Photography is the one activity you describe with energy.',
      step:'Spend 20 minutes on a photo walk before any social apps. Tonight, write one line about how the day felt.',sign:'Until tonight.'},
    future:{from:'From Future you',greet:'Hi. It’s you, a few years from now.',head:'I don’t remember whose offers they were.',
      said:'I remember this week. Everyone seemed to be getting offers, and you kept saving videos for a life you weren’t sure you wanted.',
      rec:'I don’t remember whose offers they were. I do remember the photo walks. You keep coming back to them, even on the nights you feel furthest behind.',
      step:'Go on one 20-minute photo walk today, before you check anyone else’s news.',sign:'See you down the road,\nYou'},
    diary:{from:'Plain diary',greet:'Thu 8 Oct, summary',head:'Thu 8 Oct, in four lines.',
      said:'Compared yourself with three peers’ internship offers. Saved more finance-career content. Unsure finance is the goal. Sunday’s photo walk was the best part of the week.',
      rec:'“Behind”: 3 nights this week. Photography: 2 entries, both positive.',
      step:'20-minute photo walk before opening social apps.',sign:''}
  };
  const ta=$('#entryText'), body=$('#letterBody');
  let voice='friend', edited=false, firstLine='';
  ta.value=SAMPLE;
  /* The app's planet, lit by the app's own phase maths: the terminator slides
     off its face as the entry fills up. */
  const lw=$('#lanternWrap');
  const wc=()=>{
    const n=APP.countWords(ta.value);
    $('#wc').textContent=n?APP.plural(n,'word')+'. Seal it when you are done.':'The light grows as you write';
    /* The app's own phase maths, with a floor under it: someone arriving at
       this section should see a lit planet rather than a crescent that reads
       as a fault. It still fills out to full as the entry grows. */
    if(lw)lw.setAttribute('style',APP.lanternVars(Math.max(n,96)));
  };
  ta.addEventListener('input',()=>{wc();$('#entryWarn').hidden=true});wc();
  /* The same five parts, in the same order, with the same labels the app
     prints, because APP.secLabel is the app's. */
  function render(){
    const L=LETTERS[voice];
    $('#letterFrom').textContent=L.from;
    const q=edited&&firstLine?'<button class="quote">You started with: “'+esc(firstLine)+'”</button>':'';
    body.innerHTML=
      '<header><p class="greet">'+esc(L.greet)+'</p><h1 class="headline">'+esc(L.head)+'</h1></header>'
      +'<section class="ls">'+APP.secLabel('recap')+'<div class="ls-body"><p>'+esc(L.said)+'</p>'+q+'</div></section>'
      +'<section class="ls">'+APP.secLabel('insight')+'<div class="ls-body"><div class="insight"><b>What keeps coming back</b><p>'+esc(L.rec)+'</p></div></div></section>'
      +(L.sign?'<section class="ls">'+APP.secLabel('encourage')+'<div class="ls-body"><p class="signoff">'+esc(L.sign)+'</p></div></section>':'');
    $('#stepText').textContent=L.step;
    $('#demoNote').textContent=edited?'You changed the entry. This demo letter was still written for the sample. In the app, Beyond writes it from yours.':'Demo letter written for the sample entry. In the app, Beyond writes it from your entry and the memories you allow.';
  }
  function resetStep(){$('#stepActions').hidden=false;$('#stepNote').hidden=true;$('#fixForm').hidden=true}
  $$('.lvoices button').forEach(b=>b.addEventListener('click',()=>{
    voice=b.dataset.v;$$('.lvoices button').forEach(x=>x.setAttribute('aria-selected',x===b));render();resetStep();
  }));
  render();

  $('#seal').addEventListener('click',()=>{
    const v=ta.value.trim();
    if(!v){$('#entryWarn').hidden=false;ta.focus();return}
    edited=v!==SAMPLE.trim();
    firstLine=(v.split(/(?<=[.!?])\s+/)[0]||'').slice(0,160)+((v.split(/(?<=[.!?])\s+/)[0]||'').length>160?'…':'');
    const ov=$('#overnight'), oc=$('#ovClock'), letter=$('#letter');
    const r=letter.getBoundingClientRect();
    if(r.top<0||r.top>innerHeight*.6)letter.scrollIntoView({behavior:reduce?'auto':'smooth',block:'center'});
    ov.hidden=false;ov.classList.remove('dawn');
    const a=23*60+48, b=24*60+7*60+30, start=performance.now(), dur=reduce?200:1900;
    const tick=now=>{const k=Math.min(1,(now-start)/dur), e=k<.5?2*k*k:1-Math.pow(-2*k+2,2)/2;oc.textContent=fmt(a+(b-a)*e);
      if(k>.72)ov.classList.add('dawn');
      if(k<1)requestAnimationFrame(tick);else{render();resetStep();setTimeout(()=>{ov.hidden=true},reduce?0:350)}};
    requestAnimationFrame(tick);
  });

  $('#stepActions').addEventListener('click',e=>{
    const a=e.target.closest('button')?.dataset.a;if(!a)return;
    const note=$('#stepNote');
    if(a==='fix'){$('#stepActions').hidden=true;$('#fixForm').hidden=false;$('#fixText').focus();return}
    note.textContent=a==='try'?'Added to today. Beyond won’t remind you unless you ask it to.':'Okay. Tomorrow’s letter will suggest something different.';
    note.hidden=false;$('#stepActions').hidden=true;
  });
  $('#fixCancel').addEventListener('click',resetStep);
  $('#fixForm').addEventListener('submit',e=>{e.preventDefault();
    const note=$('#stepNote');$('#fixForm').hidden=true;
    note.textContent=$('#fixText').value.trim()?'Thanks. Beyond will use your correction from tonight on.':'Nothing changed. Tell Beyond what it got wrong anytime.';
    note.hidden=false;$('#fixText').value='';
  });

  /*
   * Patterns.
   *
   * Not a drawing of the app's chart: this is the app's chart. APP.skyCard and
   * APP.drawSky are lifted out of client/web/app.src.html by the build, and
   * they are drawing Kit's real sample journal here - the same file the app
   * reads. Click a theme and the constellation it draws is the app's. The
   * magnitude rows underneath are the app's too: one dot is one night, so the
   * count can be read back rather than estimated off a bar.
   */
  (function(){
    const sky=$('#patSky'), cards=$('#patCards'), film=$('#patFilm');
    if(!sky||!KIT.length)return;
    const kept=KIT.filter(l=>l.content&&l.date&&!l.private);
    const byMonth={};
    for(const l of kept){const k=l.date.slice(0,7);(byMonth[k]=byMonth[k]||[]).push(l)}
    const months=Object.keys(byMonth).sort();
    const ym=months.slice().sort((a,b)=>byMonth[b].length-byMonth[a].length)[0];
    const list=byMonth[ym].slice().sort((a,b)=>a.date.localeCompare(b.date));
    const lastDay=new Date(+ym.slice(0,4),+ym.slice(5),0).getDate();
    const MONTHNAME=APP.MON[+ym.slice(5)-1];
    let theme=null;

    const quoteFor=(t)=>{
      for(const l of list.slice().reverse()){
        if(!APP.realThemes(l).includes(t))continue;
        const a=(l.content.analysis||[]).find(x=>x.quote);
        if(a)return a.quote;
      }
      return null;
    };

    function draw(){
      const counts=APP.countThemes(list);
      sky.innerHTML=APP.skyCard(APP.plural(list.length,'night')+' written in '+MONTHNAME,counts.slice(0,6),theme);
      APP.chart({list,from:ym+'-01',to:ym+'-'+String(lastDay).padStart(2,'0'),ticks:'month',theme:()=>theme});
      cards.innerHTML=
        '<section class="qcard"><h3 class="qh">What took up the month</h3>'
        +(counts.slice(0,3).map(([t,c])=>{
          const q=quoteFor(t);
          return '<div class="theme-line"><div class="mag"><i class="mag-name">'+esc(APP.cap(APP.THEMES[t]))+'</i>'
            +'<span class="mag-dots" aria-hidden="true">'+'<i class="lit"></i>'.repeat(c)+'<i></i>'.repeat(Math.max(0,list.length-c))+'</span>'
            +'<b class="mag-n">'+c+'<span class="mag-of"> of '+list.length+'</span></b></div>'
            +(q?'<p class="quote">“'+esc(q)+'”</p>':'')+'</div>';
        }).join('')||'<p class="fine">Mostly ordinary days.</p>')
        +'<p class="fine">Counted in nights, one dot each. Nothing is scored.</p></section>'
        +'<section class="qcard"><h3 class="qh">What you did</h3>'
        +'<span class="big">'+list.filter(l=>l.content.steps&&l.content.steps.length).length+'<small> nights with a step to try</small></span>'
        +'<p class="fine">Every to-do is optional. Finishing all three of a letter\u2019s steps earns it a gold seal.</p></section>';
      film.innerHTML=months.map(k=>{
        const ls=byMonth[k], top=APP.countThemes(ls)[0];
        const q=(ls.slice().reverse().map(l=>(l.content.analysis||[]).find(x=>x.quote)).find(Boolean)||{}).quote;
        return '<button class="frame"><span class="k">'+APP.MON[+k.slice(5)-1]+' '+k.slice(0,4)+'</span>'
          +'<p>'+(q?'“'+esc(q)+'”':esc(APP.cap(top?APP.THEMES[top[0]]:'an ordinary month')))+'</p>'
          +'<span class="k">'+APP.plural(ls.length,'night')+(top?', mostly '+esc(APP.THEMES[top[0]]):'')+'</span></button>';
      }).join('')+'<div class="frame is-blank"><span class="k">Next month</span><p>Not written yet.</p><span></span></div>';
    }
    draw();

    /* A theme draws its constellation; a star shows the night behind it. */
    sky.addEventListener('click',e=>{
      const chip=e.target.closest('[data-theme]');
      if(chip){theme=theme===chip.dataset.theme?null:chip.dataset.theme;draw();return}
      const star=e.target.closest('[data-star]');
      if(star){APP.tip(APP.tipId&&APP.tipId()===star.dataset.star?null:star.dataset.star);draw();return}
      if(e.target.closest('[data-open]'))location.href='/app';
    });
  })();

  /* Memory */
  let mems=[
    {t:'First-year university student',s:'You told Beyond · 3 Sep'},
    {t:'Photography is what makes a week feel like yours',s:'From 2 entries'},
    {t:'Internship posts tend to spiral your evening',s:'From 3 entries'},
    {t:'Sleeps badly the week before deadlines',s:'From 4 entries'},
    {t:'Prefers short, direct letters',s:'From your settings'}
  ];
  const list=$('#memList'), toast=$('#toast');let lastGone=null, toastTimer;
  function drawMems(){
    list.innerHTML=mems.length?mems.map((m,i)=>'<li class="mem" data-i="'+i+'"><p>'+esc(m.t)+'</p><span class="fine">'+esc(m.s)+'</span><span class="mem-acts"><button class="link" data-act="edit">Edit</button><button class="link" data-act="forget">Forget</button></span></li>').join(''):'<li class="mem"><p class="fine">Beyond doesn’t remember anything about you. Letters will use each night’s entry only.</p></li>';
  }
  drawMems();
  list.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;const li=b.closest('li'), i=+li.dataset.i;
    if(b.dataset.act==='forget'){
      li.classList.add('leaving');
      setTimeout(()=>{lastGone={m:mems[i],i};mems.splice(i,1);drawMems();
        $('#toastText').textContent='Forgotten. Beyond won’t use this again.';toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,5000)},reduce?0:280);
    }else if(b.dataset.act==='edit'){
      const span=$('p',li);const inp=document.createElement('input');inp.className='login-in';inp.value=mems[i].t;inp.id='memEdit'+i;inp.setAttribute('aria-label','Edit memory');
      span.replaceWith(inp);inp.focus();inp.select();b.textContent='Save';b.dataset.act='save';
    }else if(b.dataset.act==='save'){
      const inp=$('input',li);const v=inp.value.trim();if(v){mems[i].t=v;mems[i].s='Edited by you';}drawMems();
    }
  });
  list.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT'){e.preventDefault();e.target.closest('li').querySelector('[data-act="save"]').click()}if(e.key==='Escape'&&e.target.tagName==='INPUT')drawMems()});
  $('#undo').addEventListener('click',()=>{if(lastGone){mems.splice(lastGone.i,0,lastGone.m);lastGone=null;drawMems()}toast.hidden=true});
  $('#memSwitch').addEventListener('click',function(){
    const on=this.getAttribute('aria-checked')!=='true';this.setAttribute('aria-checked',on);
    $('#memLabel').textContent=on?'Memory on':'Memory paused';list.classList.toggle('paused',!on);$('#pausedMsg').hidden=on;
  });

  /* Join (demo) */
  $('#joinForm').addEventListener('submit',e=>{e.preventDefault();
    const v=$('#email').value.trim(), msg=$('#joinMsg');
    msg.textContent=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)?'Thanks! This is a demo page, so nothing was sent yet.':'Enter an email address like you@university.edu.';
  });

  return () => { for (const c of cleanups) c(); };
}
